/* global chrome */

// optionsStore.js
// Универсальный стор поверх chrome.storage.{local|sync} с дефолтами, миграциями и подписками

/**
 * @typedef {Object} OptionsSchema
 * @property {number} version - версия схемы
 * @property {Record<string, any>} defaults - дефолтные значения по ключам
 * @property {(all:Record<string,any>, fromVersion:number)=>Record<string,any>=} migrate - функция миграции
 */

/** Глубокое объединение (простое, без массивов-спец.логики) */
function deepMerge(target, source) {
  if (typeof target !== 'object' || target === null) return source;
  if (typeof source !== 'object' || source === null) return target;
  const out = Array.isArray(target) ? target.slice() : { ...target };
  for (const k of Object.keys(source)) {
    const sv = source[k];
    const tv = out[k];
    if (sv && typeof sv === 'object' && !Array.isArray(sv)) {
      out[k] = deepMerge(tv && typeof tv === 'object' ? tv : {}, sv);
    } else {
      out[k] = sv;
    }
  }
  return out;
}

/** Обёртка над chrome.storage.{area} в промисы */
function makeArea(area) {
  const api = chrome.storage[area];
  return {
    get(keys) {
      return new Promise((resolve) => api.get(keys, resolve));
    },
    set(obj) {
      return new Promise((resolve) => api.set(obj, resolve));
    },
    remove(keys) {
      return new Promise((resolve) => api.remove(keys, resolve));
    },
    clear() {
      return new Promise((resolve) => api.clear(resolve));
    }
  };
}

function createOptionsStore({ area = 'local' } = {}) {
  const storage = makeArea(area);
  /** @type {OptionsSchema|null} */
  let schema = null;
  const META_KEY = '__meta__options__';

  /** Инициализация: применяем дефолты и миграции один раз на старте */
  async function init(userSchema) {
    schema = userSchema;
    const res = await storage.get(null); // всё содержимое area
    const meta = res[META_KEY] || { version: 0 };
    let all = { ...res };

    // миграция
    if (schema.migrate && meta.version < schema.version) {
      all = schema.migrate(all, meta.version) || all;
      all[META_KEY] = { version: schema.version };
      await storage.set(all);
    }

    // проставить дефолты, если какие-то ключи отсутствуют
    const toSet = {};
    for (const [key, defVal] of Object.entries(schema.defaults || {})) {
      if (!(key in all)) {
        toSet[key] = defVal;
      } else if (typeof defVal === 'object' && defVal !== null) {
        // аккуратно дозаполним вложенные дефолты
        const merged = deepMerge(defVal, all[key]);
        toSet[key] = merged;
      }
    }
    if (Object.keys(toSet).length) {
      await storage.set({ ...toSet, [META_KEY]: { version: schema.version } });
    } else if (meta.version !== schema.version) {
      await storage.set({ [META_KEY]: { version: schema.version } });
    }
  }

  /** Получить значение ключа с подмешиванием дефолтов из схемы */
  async function get(key) {
    const res = await storage.get([key]);
    const val = res[key];
    const defVal = schema?.defaults?.[key];
    if (val === undefined) return defVal;
    if (defVal && typeof defVal === 'object' && defVal !== null) {
      return deepMerge(defVal, val);
    }
    return val;
  }

  /** Установить значение ключа */
  async function set(key, value) {
    await storage.set({ [key]: value });
  }

  /** Обновить частично: updater(curr) -> next */
  async function update(key, updater) {
    const curr = await get(key);
    const next = updater(curr);
    await set(key, next);
    return next;
  }

  /** Получить сразу несколько ключей (с дефолтами) */
  async function getMany(keys) {
    const res = await storage.get(keys);
    return keys.reduce((acc, k) => {
      const defVal = schema?.defaults?.[k];
      const val = res[k] === undefined ? defVal : res[k];
      acc[k] = defVal && typeof defVal === 'object' ? deepMerge(defVal, val) : val;
      return acc;
    }, {});
  }

  /** Сбросить ключ к дефолту (или удалить, если дефолта нет) */
  async function reset(key) {
    if (schema?.defaults?.hasOwnProperty(key)) {
      await set(key, schema.defaults[key]);
    } else {
      await storage.remove([key]);
    }
  }

  /** Полная очистка (осторожно!) */
  async function clearAll() {
    await storage.clear();
  }

  /**
   * Подписка на изменения ключей в этом area.
   * @param {string|string[]} keys
   * @param {(payload:{key:string, oldValue:any, newValue:any})=>void} cb
   * @returns {()=>void} unsubscribe
   */
  function watch(keys, cb) {
    const watchSet = new Set(Array.isArray(keys) ? keys : [keys]);
    const handler = (changes, changedArea) => {
      if (changedArea !== area) return;
      for (const [k, diff] of Object.entries(changes)) {
        if (!watchSet.has(k)) continue;
        cb({ key: k, oldValue: diff.oldValue, newValue: diff.newValue });
      }
    };
    chrome.storage.onChanged.addListener(handler);
    return () => chrome.storage.onChanged.removeListener(handler);
  }

  return { init, get, set, update, getMany, reset, clearAll, watch };
}

/** ===== Пример конкретного стора под твой кейс ===== */
const defaultImgOptions = {
  addNoise: true,
  noiseAmount: 8,        // 0..100 (если у тебя 0..1 — поменяй дефолт)
  type: 'image/jpeg',
  quality: 0.92          // 0..1
};

const defaultVideoOptions = {
  format: 'mp4',       // 'mp4' | 'webm'
  noiseStrength: 0.1,  // заметное зерно
  fps: 30,
  dropFirstFrame: false,
  dropLastFrame: false,
  mimeType: 'video/webm;codecs=vp9,opus',
  videoBitsPerSecond: 3_000_000,
  audioBitsPerSecond: 128_000,
  playbackRate: 1.0      // можно 2.0 чтобы ускорить запись в 2 раза
};

const defaults = {
  imgOptions: defaultImgOptions,
  videoOptions: defaultVideoOptions,
  enableCustomDownloadOpt: false,
  enableCustomDownloadVideoOpt: false
};

// если когда-то поменяем структуру — распишем миграцию тут
function migrate(all, fromVersion) {
  let out = { ...all };
  switch (fromVersion) {
    case 0:
      // пример: переименование ключа
      if (out.video && !out.videoOptions) {
        out.videoOptions = out.video;
        delete out.video;
      }
      break;
    default:
      break;
  }
  return out;
}

// Экспорт готового стора
export const options = createOptionsStore({
  area: 'local' // поменяй на 'sync', если хочешь синхронизацию между устройствами
});

// Инициализировать СХЕМУ с дефолтами и миграцией (вызови один раз при старте расширения/страницы)
export async function initOptions() {
  await options.init({
    version: 1,
    defaults,
    migrate
  });
}
