/*global chrome*/
import {options} from "../content/optionsStore";

const readLocalStorage = async (key) => {
  return new Promise((resolve, reject) => {
    chrome.storage.local.get([key], function (result) {
      if (result[key] === undefined) {
        resolve(null);
      } else {
        resolve(result[key]);
      }
    });
  });
};

const timeConverter = (timestamp) =>{
  const a = new Date(timestamp);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const year = a.getFullYear();
  // const month = months[a.getMonth()];
  const month = a.getMonth() + 1;
  const date = a.getDate();
  const hour = a.getHours();
  const min = a.getMinutes();
  const sec = a.getSeconds();
  const time = date + '.' + month + '.' + year;
  return time;
}

const getSeparateTime = (date) => {
  const months = [{name: 'Jan', pos: 1}, {name: 'Feb', pos: 2}, {name: 'Mar', pos: 3}, {name: 'Apr', pos: 4}, {name: 'May', pos: 5}, {name: 'Jun', pos: 6}, {name: 'Jul', pos: 7}, {name: 'Aug', pos: 8}, {name: 'Sep', pos: 9}, {name: 'Oct', pos: 10}, {name: 'Nov', pos: 11}, {name: 'Dec', pos: 12}];
  const month = months.find((month, index) => date.includes(month.name) && index + 1)
  const withOutComa = date.replace(',', '')
  const dayYear = withOutComa.split(' ').filter((e, index) => Number(e));
  const dat = dayYear.reduce((acc, item, currentIndex) => {
    if (currentIndex === 0) {
      return item + '.' + month.pos
    }
    return acc + '.' + item
  }, '');

  return dat;
};

