function rafBatch(fn) {
  let scheduled = false;
  return (...args) => {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(async () => {
      scheduled = false;
      try { await fn(...args); } catch (e) { console.error(e); }
    });
  };
}

export async function initDownloadOptionsImg(imgOptions) {
  const elNoise   = document.getElementById('noiseAmount');
  const elQuality = document.getElementById('quality');
  const outNoise  = document.getElementById('noiseValue');
  const outQ      = document.getElementById('qualityValue');
  const outQp     = document.getElementById('qualityPercent');
  const btnReset  = document.getElementById('resetImgControls');

  // 1) загрузка из стора + первичная отрисовка
  const stored = await options.get('imgOptions');
  Object.assign(imgOptions, stored);

  elNoise.value   = String(imgOptions.noiseAmount);
  elQuality.value = String(imgOptions.quality);

  const render = () => {
    outNoise.textContent = String(elNoise.value);
    const q = Number(elQuality.value) || 0;
    outQ.textContent  = q.toFixed(2);
    outQp.textContent = `(${Math.round(q * 100)}%)`;
  };
  render();

  // 2) изменения с ползунков -> стор + перерисовка + window.*
  const emit = rafBatch(async () => {
    const next = {
      ...imgOptions,
      noiseAmount: Number(elNoise.value),
      quality: Number(elQuality.value),
    };
    Object.assign(imgOptions, next);
    window.imgOptions = { ...(window.imgOptions || {}), ...next };
    render();
    await options.set('imgOptions', next);
  });

  elNoise  .addEventListener('input',  emit);
  elQuality.addEventListener('input',  emit);
  btnReset ?.addEventListener('click', () => {
    elNoise.value   = '8';
    elQuality.value = '0.92';
    emit();
  });

  // 3) внешние изменения (другая вкладка/страница) -> UI + объект
  options.watch('imgOptions', ({ newValue }) => {
    if (!newValue) return;
    if (String(elNoise.value)   !== String(newValue.noiseAmount)) elNoise.value   = String(newValue.noiseAmount);
    if (String(elQuality.value) !== String(newValue.quality))     elQuality.value = String(newValue.quality);
    Object.assign(imgOptions, newValue);
    render();
  });
}

export async function initDownloadOptionsVideo(videoOptions) {
  const elNoise   = document.getElementById('noiseAmountVideo');  // ВАЖНО: именно этот id
  const outNoise  = document.getElementById('noiseValueVideo');
  const formatSel = document.getElementById('videoFormat');
  const btnReset  = document.getElementById('resetVideoControls');

  const stored = await options.get('videoOptions');
  Object.assign(videoOptions, stored);

  elNoise.value = String(videoOptions.noiseStrength);
  if (formatSel?.querySelector(`option[value="${videoOptions.format}"]`)) {
    formatSel.value = videoOptions.format;
  }

  const render = () => {
    outNoise.textContent = String(elNoise.value);
  };
  render();

  const emit = rafBatch(async () => {
    const next = {
      ...videoOptions,
      noiseStrength: Number(elNoise.value),
      format: formatSel?.value,
    };
    Object.assign(videoOptions, next);
    window.videoOptions = { ...(window.videoOptions || {}), ...next };
    render();
    await options.set('videoOptions', next);
  });

  elNoise .addEventListener('input',  emit);
  formatSel?.addEventListener('change', emit);
  btnReset?.addEventListener('click', () => {
    elNoise.value = '0.1';

    if (formatSel) {
      formatSel.value = 'mp4';
    }

    emit();
  });

  options.watch('videoOptions', ({ newValue }) => {
    if (!newValue) return;
    if (String(elNoise.value) !== String(newValue.noiseStrength)) {
      elNoise.value = String(newValue.noiseStrength);
    }
    if (newValue.format &&
      newValue.format !== formatSel?.value &&
      formatSel?.querySelector(`option[value="${newValue.format}"]`)) {
      formatSel.value = newValue.format;
    }
    Object.assign(videoOptions, newValue);
    render();
  });
}

export default {
  readLocalStorage,
  timeConverter,
  getActiveTime,
  initDownloadOptionsVideo,
  initDownloadOptionsImg
}