
const toSnakeCase = (str) =>{
  return str
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .toLowerCase();
}

const transformKeysToSnakeCase = (obj) => {
  if (!obj) {
    return;
  }
  if (Array.isArray(obj)) {
    return obj.map(transformKeysToSnakeCase);
  }

  if (obj !== null && typeof obj === 'object') {
    const newObj = {};
    for (const key in obj) {
      const snakeKey = toSnakeCase(key);
      newObj[snakeKey] = transformKeysToSnakeCase(obj[key]);
    }
    return newObj;
  }

  return obj;
}

// === helpers ===
const clamp255 = (v) => (v < 0 ? 0 : (v > 255 ? 255 : v));

// ---- helpers: ext <-> mime, парсинг расширения, выбор типа ----
const EXT_TO_MIME = {
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  png: 'image/png',
  webp: 'image/webp'
};

const MIME_TO_EXT = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp'
};

const getExtFromUrl = (src) => {
  try {
    // убираем query/fragment, берём только конец path
    const u = new URL(src, window.location.href);
    const m = u.pathname.match(/\.([a-z0-9]+)$/i);
    return m ? m[1].toLowerCase() : '';
  } catch {
    // относительные/нестандартные строки
    const clean = String(src).split(/[?#]/)[0];
    const m = clean.match(/\.([a-z0-9]+)$/i);
    return m ? m[1].toLowerCase() : '';
  }
};

// Выбор типа: сперва по расширению, если его нет — по заголовку Content-Type, иначе JPEG
const chooseTypeByExtension = (src, headerContentType = '') => {
  const ext = getExtFromUrl(src);
  if (ext && EXT_TO_MIME[ext]) return EXT_TO_MIME[ext];
  if (headerContentType && /^image\//i.test(headerContentType)) {
    return headerContentType.split(';')[0].toLowerCase();
  }
  return 'image/jpeg';
};

// Применить расширение под финальный MIME
const extForMime = (type) => MIME_TO_EXT[type] || 'jpg';

const addNoiseToImageData = (imageData, amount = 8) => {
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const n = (Math.random() * 2 - 1) * amount; // -amount..+amount
    data[i]     = clamp255(data[i]     + n); // R
    data[i + 1] = clamp255(data[i + 1] + n); // G
    data[i + 2] = clamp255(data[i + 2] + n); // B
    // альфу не трогаем
  }
};

const processImageBlob = async (
  inputBlob,
  { addNoise = true, noiseAmount = 8, type = 'image/jpeg', quality = 0.92 } = {}
) => {
  const img = await createImageBitmap(inputBlob);

  const canvas = (typeof OffscreenCanvas !== 'undefined')
    ? new OffscreenCanvas(img.width, img.height)
    : Object.assign(document.createElement('canvas'), { width: img.width, height: img.height });

  const ctx = canvas.getContext('2d', { willReadFrequently: !!addNoise });
  ctx.drawImage(img, 0, 0);

  if (addNoise) {
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    addNoiseToImageData(imageData, noiseAmount);
    ctx.putImageData(imageData, 0, 0);
  }

  const outBlob = canvas.convertToBlob
    ? await canvas.convertToBlob({ type, quality })
    : await new Promise((r) => canvas.toBlob(r, type, quality));

  img.close?.();
  return outBlob;
};

const downloadBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
};


export default {
  downloadBlob,
  processImageBlob,
  extForMime,
  chooseTypeByExtension
}