const renderSubattachments = (subattachments) => {
  return subattachments.map(sub => {
    return `<div class="swiper-slide">
                ${sub?.isVideo ? `<video class="mediaContentVideo" src="${sub?.contentSrc}" controls></video>` : `<img class="mediaContentImage" src="${sub?.contentSrc}">`}                   
                <div class="likesWrapper">
                    ${sub.linkTitle ? `<div class="subAction">                      
                      <a href="${sub.link}" target="_blank" class="showMoreLink actionLink">${sub.linkTitle || 'Show More'}</a>
                    </div>` : ''}
                    <br/>
                    ${sub.description ? `<p class="subAttachmentDesc">${sub.description}</p>` : ''}
                    ${renderLinkRedirect(sub.link, subattachments.length)}
                </div>               
            </div>`
  }).join('');
};

