const downloadMedia = async (event, slider) => {
  try {

    const parentNode = event?.target?.parentNode?.parentNode?.parentNode.parentNode.parentNode;

    if (!parentNode) {
      return;
    }

    const titleNode = !slider && parentNode.querySelector('.titleAds');
    const mediaVideo = parentNode.querySelectorAll('.mediaContentVideo');
    const mediaImage = parentNode.querySelectorAll('.mediaContentImage');

    const {useImg, useVideo, effImgOptions, effVideoOptions} = await getEffectiveDownloadOptions({
      imgFallback: imgOptions,
      videoFallback: videoOptions,
    });

    const adsData = await utils.readLocalStorage('adsList');
    const mappedAdsData = adsData && Object.values(adsData);
    const ad = mappedAdsData?.length && event.target.getAttribute('ad-id') && mappedAdsData.find(e => e.pageId === event.target.getAttribute('ad-id'));

    if (useImg) {
      if (mediaImage?.length) {
        for (const image of Array.from(mediaImage)) {
          const src = image.getAttribute("src");
          if (!src) continue;

          const response = await fetch(src, { credentials: 'omit' });
          const originalBlob = await response.blob();

          const detectedType = utilsImage.chooseTypeByExtension(src, response.headers.get('Content-Type') || originalBlob.type);
          const finalType = detectedType || imgOptions?.type;

          const processedBlob = await utilsImage.processImageBlob(originalBlob, {
            ...effImgOptions,
            type: finalType,
          });
          // utils.downloadBlob(processedBlob, `image - ${Date.now()}.jpg`);
          utilsImage.downloadBlob(processedBlob, `image processed- ${Date.now()}.${utilsImage.extForMime(finalType)}`);
        }
      }
    } else {
      if (mediaImage?.length) {
        const res = await Promise.all(Array.from(mediaImage).map(async image => {
          const src = image.getAttribute("src")
          const response = await fetch(src);
          const data = await response.blob();
          return data;
        }));

        res.map(data => {
          const ref = document.createElement("a");
          ref.href = URL.createObjectURL(data);
          ref.download = `image - ${Date.now()}.jpg`;
          ref.click();
        });
      }
    }

    if (useVideo) {
      if (mediaVideo?.length) {
        const btn = event?.target?.closest('.downloadMedia') || event?.target;
        const ui = makeButtonProgress(btn);

        // утилиты прогресса
        let totalTasks = 0;     // сколько всего единиц работы (картинок + видео)
        let finishedTasks = 0;  // сколько задач завершено
        let currentOverallPct = 0;

        // пересчёт общего процента: finished + доля текущего
        const setOverall = (partialPctOfCurrentItem = 0) => {
          // каждый item даёт равный вклад = 100/totalTasks
          const perItemWeight = totalTasks > 0 ? (100 / totalTasks) : 100;
          const pct = Math.max(0, Math.min(100,
            finishedTasks * perItemWeight + partialPctOfCurrentItem * (perItemWeight / 100)
          ));
          currentOverallPct = pct;
          ui.set(pct);
        };
        const hasHD = ad?.adData?.videoURLs?.length || ad?.adData?.video_hd_url;

        for (const [index, video] of Array.from(mediaVideo).entries()) {
          const src = hasHD && (ad?.adData?.video_hd_url || ad?.adData?.videoURLs?.[index]?.video_hd_url)
            ? (ad?.adData?.video_hd_url || ad?.adData?.videoURLs?.[index]?.video_hd_url)
            : video.getAttribute('src');
          if (!src) continue;

          const resp = await fetch(src, { credentials: 'omit' });
          const originalBlob = await resp.blob();
          // пробрасываем onProgress из MediaRecorder в общий прогресс (доля текущего item)

          const {outBlob, format} = await processVideoWithMediaRecorder(originalBlob, {
            ...effVideoOptions,
            onProgress: ({ pct }) => setOverall(pct || 0)
          });

          // const formatFile = format === 'mp4' ? 'mp4' : 'webm';

          const mime = outBlob.type || 'video/webm';
          const ext  = extForMime(mime);

          utilsImage.downloadBlob(outBlob, `video-processed-${Date.now()}.${ext}`);
          finishedTasks++;
          setOverall(0); // завершили этот item => фиксируем добавление
        }
        ui.done();

      }
    } else {
      if (mediaVideo?.length) {
        const isContainHDUrl = ad?.adData?.videoURLs?.length || ad?.adData?.video_hd_url;

        const res = await Promise.all(Array.from(mediaVideo).map(async (video, index) => {
          const src = isContainHDUrl && (ad?.adData?.video_hd_url || ad?.adData?.videoURLs[index]?.video_hd_url) ? ad?.adData?.video_hd_url || ad?.adData?.videoURLs[index]?.video_hd_url : video.getAttribute("src");
          const response = await fetch(src);
          const data = await response.blob();
          return data;
        }));

        res.map(data => {
          const ref = document.createElement("a");
          ref.href = URL.createObjectURL(data);
          ref.download = `video - ${Date.now()}.mp4`;
          ref.click();
        })
      }
    }

  } catch (error) {
    console.log(error)
    alert("Error downloading video");
  }
};

const reHideDescription = (event) => {
  const reHideNode = event?.target;
  const desc = event?.target.parentNode.parentNode.parentNode.parentNode.querySelector('.adsDescription');

  if (reHideNode.innerText === 'Read more') {
    reHideNode.innerText = 'Read less';
    desc.classList.remove('adsDescriptionHeightMin');
  } else {
    reHideNode.innerText = 'Read more';
    desc.classList.add('adsDescriptionHeightMin');
  }

};

const setShowType = (event) => {
  const showId = event?.target.id;

  if (showType === showId) {
    return;
  }

  const btns = document.querySelectorAll('.showButton');
  showType = showId;
  Array.from(btns).map(btn => btn.classList.remove('activeType'))
  render();
}

document.body.addEventListener('click', async function (event) {
  if (event.target.classList.contains('downloadMedia') && !event.target.classList.contains('downloadMediaSlider')) {
    downloadMedia(event);
    return;
  }

  if (event.target.classList.contains('downloadMediaSlider')) {
    downloadMedia(event, true);
    return;
  }

  if (event.target.classList.contains('clearAds')) {
    chrome.storage.local.set({'adsList': null}, function () {
      window.location.reload(true);
    });
    return;
  }

  if (event.target.classList.contains('showMoreDescription')) {
    reHideDescription(event);
    return;
  }

  if (event.target.classList.contains('showButton')) {
    setShowType(event);
    return;
  }

  if (event.target.classList.contains("copyLinkBtn")) {
    const link = event.target.getAttribute("data-link");
    try {
      await navigator.clipboard.writeText(link);
      event.target.textContent = "Copied ✅"; // показываем галочку
      setTimeout(() => (event.target.textContent = "Copy link"), 1000);
      return;
    } catch (err) {
      console.error("Copy failed", err);
      event.target.textContent = "❌";
      setTimeout(() => (event.target.textContent = "Copy link"), 1000);
    }
  }
});


render();



