/* global chrome */
import { options } from './optionsStore.js';

/**
 * Возвращает актуальные флаги и опции скачивания:
 * - useImg/useVideo — включены ли «кастомные» настройки
 * - effImgOptions/effVideoOptions — объединение store + fallback (+ window.*)
 */
export async function getEffectiveDownloadOptions({
                                                    imgFallback = {},
                                                    videoFallback = {},
                                                    enableImgFallback = false,
                                                    enableVideoFallback = false,
                                                  } = {}) {
  // фоллбеки на локальные/глобальные значения
  let useImg = !!enableImgFallback;
  let useVideo = !!enableVideoFallback;
  let effImgOptions = { ...(window.imgOptions || {}), ...imgFallback };
  let effVideoOptions = { ...(window.videoOptions || {}), ...videoFallback };

  try {
    const [imgFromStore, videoFromStore, flags] = await Promise.all([
      options.get('imgOptions'),
      options.get('videoOptions'),
      options.getMany(['enableCustomDownloadOpt', 'enableCustomDownloadVideoOpt']),
    ]);

    if (imgFromStore)   effImgOptions   = { ...effImgOptions,   ...imgFromStore };
    if (videoFromStore) effVideoOptions = { ...effVideoOptions, ...videoFromStore };

    if (typeof flags.enableCustomDownloadOpt === 'boolean') {
      useImg = flags.enableCustomDownloadOpt;
    }
    if (typeof flags.enableCustomDownloadVideoOpt === 'boolean') {
      useVideo = flags.enableCustomDownloadVideoOpt;
    }
  } catch (e) {
    console.log('getEffectiveDownloadOptions: ' + e);
  }

  return { useImg, useVideo, effImgOptions, effVideoOptions };
}